package rules; import java.util.ArrayList;import java.util.Collections;import java.util.List; public final class RuleSet{private final List<IdsRule> rules=new ArrayList<>();public void add(IdsRule r){if(r!=null)rules.add(r);}public void addAll(java.util.Collection<IdsRule> r){if(r!=null)rules.addAll(r);}public List<IdsRule> rules(){return Collections.unmodifiableList(rules);}public int size(){return rules.size();}}
